>\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"color\":{\"background\":\"#ffb23d\",\"text\":\"#2c3066\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"right\":\"48px\",\"bottom\":\"32px\",\"left\":\"48px\"}},\"typography\":{\"fontSize\":\"20px\",\"textTransform\":\"uppercase\",\"letterSpacing\":\"1px\",\"fontStyle\":\"normal\",\"fontWeight\":\"700\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-color has-background has-custom-font-size wp-element-button\" style=\"color:#2c3066;background-color:#ffb23d;padding-top:32px;padding-right:48px;padding-bottom:32px;padding-left:48px;font-size:20px;font-style:normal;font-weight:700;letter-spacing:1px;text-transform:uppercase\">hello</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">hello</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','','','draft','open','open','','','','','2026-10-02 09:34:19','2026-10-02 09:34:19','',0,'http://localhost/wordpress/?p=36',0,'post','',0),(37,1,'2026-10-02 09:35:51','0000-00-00 00:00:00','','Professional Web Development Services','','draft','open','open','','','','','2026-10-02 09:35:51','2026-10-02 09:35:51','',0,'http://localhost/wordpress/?p=37',0,'post','',0),(38,1,'2026-10-07 09:21:35','2026-10-07 09:21:35','<!-- wp:block {\"ref\":40} /-->','hello','','trash','closed','closed','','__trashed-3','','','2026-10-07 09:21:35','2026-10-07 09:21:35','',0,'http://localhost/wordpress/?page_id=38',0,'page','',0),(39,1,'2026-10-02 09:39:15','2026-10-02 09:39:15','','cf43705e 3eff 4bdf 8c2d 7dcd66abee02','','inherit','open','closed','','cf43705e-3eff-4bdf-8c2d-7dcd66abee02',