t-weight: 700;\n  color: #1e293b;\n}\n\n.ad-author-info strong {\n  display: block;\n  color: var(--ad-dark);\n  font-size: 0.95rem;\n}\n\n.ad-author-info span {\n  font-size: 0.85rem;\n  color: #64748b;\n}\n\n/* Lead Capture Form Section */\n.ad-form-section {\n  background: #ffffff;\n  border: 1px solid var(--ad-border);\n  border-radius: 16px;\n  padding: 50px 30px;\n  max-width: 650px;\n  margin: 0 auto 60px auto;\n  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.05);\n  text-align: center;\n}\n\n.ad-form-section h3 {\n  font-size: 1.8rem;\n  color: var(--ad-dark);\n  margin-bottom: 10px;\n}\n\n.ad-form-section p {\n  color: #64748b;\n  margin-bottom: 30px;\n}\n\n.ad-form-group {\n  margin-bottom: 18px;\n  text-align: left;\n}\n\n.ad-form-group label {\n  display: block;\n  font-size: 0.9rem;\n  font-weight: 600;\n  color: var(--ad-dark);\n  margin-bottom: 6px;\n}\n\n.ad-form-group input,\n.ad-form-group select {\n  width: 100%;\n  padding: 12px 14px;\n  border: 1px solid var(--ad-border);\n  border-radius: 6px;\n  font-size: 1rem;\n  box-sizing: border-box;\n}\n\n.ad-form-group input:focus,\n.ad-form-group select:focus {\n  outline: none;\n  border-color: var(--ad-primary);\n  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);\n}\n\n.ad-form-btn {\n  width: 100%;\n  padding: 14px;\n  background: var(--ad-primary);\n  color: #ffffff;\n  font-weight: 700;\n  font-size: 1.05rem;\n  border: none;\n  border-radius: 8px;\n  cursor: pointer;\n  transition: background 0.2s ease;\n}\n\n.ad-form-btn:hover {\n  background: var(--ad-primary-dark);\n}\n\n.ad-guarantee {\n  margin-top: 15px;\n  font-size: 0.85rem;\n  color: #94a3b8;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n}\n\n@media (max-width: 768px) {\n  .ad-hero h1 {\n    font-size: 2rem;\n  }\n  .ad-promo-banner {\n    padding: 30px 20px;\n  }\n}\n\n\n<div class=\"ad-page\">\n  <div class=\"ad-container\">\n\n    <!-- 1. HERO SECTION -->\n    <section class=\"ad-hero\">\n      <div 