lor: #0f172a;\n    font-size: 1.45rem;\n    font-weight: 700;\n    margin-top: 0;\n    margin-bottom: 12px;\n    display: flex;\n    align-items: center;\n    gap: 10px;\n}\n.legal-section p, .legal-section li {\n    color: #475569;\n    font-size: 1.02rem;\n}\n.legal-section ul {\n    margin: 10px 0 15px 25px;\n}\n.legal-callout {\n    background: #eff6ff;\n    border-left: 4px solid #2563eb;\n    padding: 16px 20px;\n    border-radius: 0 8px 8px 0;\n    margin: 20px 0;\n    color: #1e40af;\n    font-size: 0.95rem;\n}\n/* Services Grid */\n.services-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\n    gap: 30px;\n    margin-bottom: 60px;\n}\n.service-card {\n    background: #ffffff;\n    border: 1px solid #e2e8f0;\n    border-radius: 16px;\n    padding: 35px 28px;\n    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);\n    transition: transform 0.25s ease, box-shadow 0.25s ease;\n    display: flex;\n    flex-direction: column;\n}\n.service-card:hover {\n    transform: translateY(-6px);\n    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.08);\n    border-color: #cbd5e1;\n}\n.service-icon {\n    width: 60px;\n    height: 60px;\n    background: #eff6ff;\n    color: #2563eb;\n    border-radius: 14px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 1.8rem;\n    margin-bottom: 22px;\n}\n.service-card h3 {\n    color: #0f172a;\n    font-size: 1.4rem;\n    font-weight: 700;\n    margin: 0 0 12px 0;\n}\n.service-card p {\n    color: #64748b;\n    font-size: 0.98rem;\n    line-height: 1.6;\n    margin-bottom: 20px;\n    flex-grow: 1;\n}\n.service-features {\n    list-style: none;\n    padding: 0;\n    margin: 0 0 25px 0;\n}\n.service-features li {\n    font-size: 0.9rem;\n    color: #334155;\n    margin-bottom: 8px;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n.service-btn {\n    display: inline-block;\n    background: #2563eb;\n    color: #ffffff !important;\n    text-align: center;\n    padding: 12px 24px;\n    border-radius: 8px;\n    font-weight: 700;\n    text-decoration: none;\n    transition: background 0.2s ease;\n}\n.service-btn:hover {\n    background: #1d4ed8;\n}\n/* CTA Strip */\n.cta-banner {\n    background: linear-gradient(135deg, #1e1b4b, #312e81);\n    color: #ffffff;\n    border-radius: 16px;\n    padding: 50px 40px;\n    text-align: center;\n}\n.cta-banner h2 {\n    color: #ffffff !important;\n    font-size: 2.2rem;\n    margin: 0 0 12px 0;\n}\n.cta-banner p {\n    color: #c7d2fe;\n    font-size: 1.15rem;\n    max-width: 600px;\n    margin: 0 auto 30px auto;\n}\n.cta-btn {\n    display: inline-block;\n    background: #f59e0b;\n    color: #0f172a !important;\n    padding: 16px 36px;\n    border-radius: 8px;\n    font-weight: 700;\n    font-size: 1.1rem;\n    text-decoration: none;\n    transition: transform 0.2s ease;\n}\n.cta-btn:hover {\n    transform: translateY(-2px);\n    background: #fbbf24;\n}\n@media (max-width: 768px) {\n    .page-hero h1 { font-size: 2rem; }\n    .legal-card { padding: 30px 20px; }\n}\n<div class=\"custom-page-wrap\">\n    <div class=\"page-hero\">\n        <span class=\"badge\">What We Do</span>\n        <h1>Our Professional Services</h1>\n        <p class=\"subtitle\">Cutting-edge web engineering, marketing strategy, and cloud solutions designed to accelerate your growth.</p>\n    </div>\n\n    <div class=\"content-container\">\n        <div class=\"services-grid\">\n            <!-- Card 1 -->\n            <div class=\"service-card\">\n                <div class=\"service-icon\">💻</div>\n                <h3>Custom Web Development</h3>\n                <p>We build responsive, blazing-fast WordPress &amp; Elementor websites with clean architecture, enterprise security, and bespoke interactivity.</p>\n                <ul class=\"service-features\">\n                    <li>✔ Custom Theme &amp; Plugin Setup</li>\n                    <li>✔ 100% Mobile &amp; Tablet Responsive</li>\n         